const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.2 11.7a8.2 8.2 0 0 1-12.1 7.2L4 20l1.1-3.9A8.2 8.2 0 1 1 20.2 11.7Z"/><path d="M8.4 8.1c.2-.4.4-.4.7-.4h.4c.2 0 .3.1.4.4l.7 1.6c.1.2.1.4 0 .5l-.5.7c-.1.2-.1.4 0 .5.5.9 1.2 1.6 2.1 2.1.2.1.4.1.5-.1l.7-.8c.1-.2.3-.2.5-.1l1.5.7c.2.1.3.2.3.4 0 .3-.1.9-.5 1.2-.4.4-1 .6-1.5.5-1-.2-2.1-.7-3.2-1.7-1-.9-1.8-2.1-2-3.1-.2-.8.1-1.5.4-1.9Z"/></svg>';
const widget=document.createElement('aside');
widget.className='support-widget is-hidden'+(document.querySelector('.bottom-nav')?' has-bottom-nav':'');widget.inert=true;widget.setAttribute('aria-hidden','true');
widget.innerHTML='<section class="support-panel" id="support-panel" aria-label="Ajuda e suporte" hidden><div class="support-panel-head"><div><strong>Como podemos ajudar?</strong><small>Escolha uma informação ou fale com a equipe.</small></div><button class="support-close" type="button" aria-label="Fechar suporte">×</button></div><nav class="support-topics" aria-label="Ajuda dentro do site"><a href="/#termos">Como funciona o Message</a><a href="/cliente/#acompanhar">Acompanhar meu pedido</a><a href="/#cancelamentos">Pagamento e cancelamento</a><a href="/#patrocinadores">Regras para patrocinadores</a><a href="/#privacidade">Privacidade</a></nav><label class="support-message-label" for="support-message">Prefere falar com a equipe?</label><textarea id="support-message" maxlength="700" placeholder="Escreva sua dúvida ou o que precisa."></textarea><button class="support-send" type="button">Continuar no WhatsApp '+icon+'</button><p class="support-footnote">Você revisa a mensagem no WhatsApp antes de enviá-la.</p></section><button class="support-launcher" type="button" aria-label="Abrir suporte pelo WhatsApp" aria-expanded="false" aria-controls="support-panel">'+icon+'<span>Suporte</span></button>';
document.body.append(widget);
const launcher=widget.querySelector('.support-launcher'),panel=widget.querySelector('.support-panel'),input=widget.querySelector('#support-message');
function close(){panel.hidden=true;launcher.setAttribute('aria-expanded','false')}
launcher.addEventListener('click',()=>{panel.hidden=!panel.hidden;launcher.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){reveal();widget.querySelector('.support-close').focus()}});
widget.querySelector('.support-close').addEventListener('click',()=>{close();launcher.focus()});
widget.querySelectorAll('.support-topics a').forEach(link=>link.addEventListener('click',close));
widget.querySelector('.support-send').addEventListener('click',()=>{const message=input.value.trim();if(!message){input.focus();input.setCustomValidity('Escreva sua dúvida para continuar.');input.reportValidity();return}input.setCustomValidity('');const url='https://wa.me/5514991088104?text='+encodeURIComponent('Olá, preciso de ajuda com o Hocco Message. '+message);const tab=window.open(url,'_blank','noopener,noreferrer');if(!tab)location.href=url});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden){close();launcher.focus()}});

let previousY=window.scrollY||0,lastDirection='up',revealTimer;
function conceal(){if(!panel.hidden||widget.contains(document.activeElement))return;widget.classList.add('is-hidden');widget.inert=true;widget.setAttribute('aria-hidden','true')}
function reveal(){widget.classList.remove('is-hidden');widget.inert=false;widget.setAttribute('aria-hidden','false')}
window.addEventListener('scroll',()=>{const y=window.scrollY||0,delta=y-previousY;previousY=y;if(Math.abs(delta)<2)return;lastDirection=delta>0?'down':'up';conceal();clearTimeout(revealTimer);if(lastDirection==='down'&&y>80){revealTimer=setTimeout(()=>{if(lastDirection==='down'&&window.scrollY>80&&panel.hidden)reveal()},500)}},{passive:true});
